-- NULL timestamps, duplicates, and rows on each side of both day boundaries
CREATE OR REPLACE TABLE events AS SELECT * FROM (VALUES
  (1, CAST('2023-12-31 23:59:59' AS TIMESTAMP)),
  (2, CAST('2024-01-01 00:00:00' AS TIMESTAMP)),
  (3, CAST('2024-01-01 12:30:00' AS TIMESTAMP)),
  (3, CAST('2024-01-01 12:30:00' AS TIMESTAMP)),
  (4, CAST('2024-01-01 23:59:59' AS TIMESTAMP)),
  (5, CAST('2024-01-02 00:00:00' AS TIMESTAMP)),
  (6, CAST(NULL AS TIMESTAMP)),
  (6, CAST(NULL AS TIMESTAMP))
) AS v(id, ts);
